import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"03 · 树与堆","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/dsa/03.md","filePath":"bagu/dsa/03.md"}'),l={name:"bagu/dsa/03.md"};function o(e,s,i,r,g,c){return n(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="_03-·-树与堆" tabindex="-1">03 · 树与堆 <a class="header-anchor" href="#_03-·-树与堆" aria-label="Permalink to &quot;03 · 树与堆&quot;">​</a></h1><blockquote><p>这一篇是 04 数据库的前置。<strong>不先搞懂&quot;树高决定查找次数&quot;，B+ 树就只是死记硬背。</strong></p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><ul><li><strong>树</strong>：用&quot;分叉&quot;把查找范围一层层砍半，把 O(n) 变成 O(log n)。</li><li><strong>堆</strong>：只维护&quot;局部有序&quot;（父节点 ≥ 或 ≤ 子节点），用最小代价拿到最值。</li></ul><h2 id="生活类比" tabindex="-1">生活类比 <a class="header-anchor" href="#生活类比" aria-label="Permalink to &quot;生活类比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结构</th><th>场景</th></tr></thead><tbody><tr><td>二叉树</td><td>家族族谱，每个人最多两个孩子</td></tr><tr><td>二叉搜索树</td><td>查字典：大了往后翻，小了往前翻</td></tr><tr><td>平衡树</td><td>一个强迫症管理员，每次放书后都要把书架调平</td></tr><tr><td>堆</td><td>急诊分诊：不要求全员排队有序，只要求&quot;最严重的永远在最前面&quot;</td></tr><tr><td>完全二叉树</td><td>剧院座位：一排排坐满，最后一排从左往右坐</td></tr></tbody></table><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、二叉树的四种遍历-必须能默写" tabindex="-1">一、二叉树的四种遍历（必须能默写） <a class="header-anchor" href="#一、二叉树的四种遍历-必须能默写" aria-label="Permalink to &quot;一、二叉树的四种遍历（必须能默写）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        1</span></span>
<span class="line"><span>       / \\</span></span>
<span class="line"><span>      2   3</span></span>
<span class="line"><span>     / \\   \\</span></span>
<span class="line"><span>    4   5   6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>前序（根左右）：1 2 4 5 3 6     &lt; 复制一棵树</span></span>
<span class="line"><span>中序（左根右）：4 2 5 1 3 6     &lt; 二叉搜索树的中序是升序！</span></span>
<span class="line"><span>后序（左右根）：4 5 2 6 3 1     &lt; 释放内存、算表达式</span></span>
<span class="line"><span>层序（BFS）  ：1 2 3 4 5 6     &lt; 用队列</span></span></code></pre></div><p><strong>中序遍历 BST 得到升序序列</strong>——这是 BST 最重要的性质，面试常考&quot;验证 BST&quot;就是用这个。</p><h3 id="二、二叉搜索树-bst" tabindex="-1">二、二叉搜索树（BST） <a class="header-anchor" href="#二、二叉搜索树-bst" aria-label="Permalink to &quot;二、二叉搜索树（BST）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规则：左子树所有节点 &lt; 根 &lt; 右子树所有节点</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        8</span></span>
<span class="line"><span>       / \\</span></span>
<span class="line"><span>      3   10</span></span>
<span class="line"><span>     / \\    \\</span></span>
<span class="line"><span>    1   6    14</span></span>
<span class="line"><span>       / \\   /</span></span>
<span class="line"><span>      4   7 13</span></span>
<span class="line"><span></span></span>
<span class="line"><span>查找 6：8 &gt; 左 &gt; 3 &gt; 右 &gt; 6     （3 次比较，而不是 7 次）</span></span></code></pre></div><p><strong>查找复杂度 = 树高</strong>。</p><p><strong>致命问题：退化成链表</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按 1,2,3,4,5 顺序插入：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1</span></span>
<span class="line"><span> \\</span></span>
<span class="line"><span>  2</span></span>
<span class="line"><span>   \\</span></span>
<span class="line"><span>    3</span></span>
<span class="line"><span>     \\</span></span>
<span class="line"><span>      4</span></span>
<span class="line"><span>       \\</span></span>
<span class="line"><span>        5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>查找 5 &gt; 要比较 5 次，退化成 O(n)</span></span></code></pre></div><p><strong>为什么会退化</strong>：BST 的形态完全由插入顺序决定。有序插入是最坏情况。</p><h3 id="三、平衡树-怎么-保持平衡" tabindex="-1">三、平衡树：怎么&quot;保持平衡&quot; <a class="header-anchor" href="#三、平衡树-怎么-保持平衡" aria-label="Permalink to &quot;三、平衡树：怎么&quot;保持平衡&quot;&quot;">​</a></h3><p><strong>AVL 树</strong>：严格要求&quot;左右子树高度差 ≤ 1&quot;，不平衡就旋转。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>四种不平衡（以&quot;失衡节点&quot;为参照）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LL（左左）：插入到左子树的左边 &gt; 右旋</span></span>
<span class="line"><span>RR（右右）：插入到右子树的右边 &gt; 左旋</span></span>
<span class="line"><span>LR（左右）：插入到左子树的右边 &gt; 先左旋再右旋</span></span>
<span class="line"><span>RL（右左）：插入到右子树的左边 &gt; 先右旋再左旋</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>右旋示意：</span></span>
<span class="line"><span>      y                x</span></span>
<span class="line"><span>     / \\              / \\</span></span>
<span class="line"><span>    x   C    &gt;       A   y</span></span>
<span class="line"><span>   / \\                  / \\</span></span>
<span class="line"><span>  A   B                B   C</span></span></code></pre></div><p><strong>红黑树</strong>：不追求严格平衡，用&quot;颜色 + 5 条规则&quot;保证&quot;最长路径 ≤ 最短路径的 2 倍&quot;，树高仍是 O(log n)。</p><table tabindex="0"><thead><tr><th></th><th>AVL</th><th>红黑树</th></tr></thead><tbody><tr><td>平衡程度</td><td>严格（高度差 ≤1）</td><td>宽松（最长 ≤ 2×最短）</td></tr><tr><td>查找</td><td>略快（树更矮）</td><td>略慢</td></tr><tr><td>插入删除</td><td>慢（旋转多）</td><td>快（旋转少）</td></tr><tr><td>用在哪</td><td>读多写少</td><td>通用（Java TreeMap、Linux 内核、C++ map）</td></tr></tbody></table><p><strong>为什么工程上多用红黑树</strong>：插入删除的旋转次数少，综合性能更好。<strong>AVL 更适合&quot;读远多于写&quot;的场景</strong>。</p><h3 id="四、堆-用数组实现的完全二叉树" tabindex="-1">四、堆：用数组实现的完全二叉树 <a class="header-anchor" href="#四、堆-用数组实现的完全二叉树" aria-label="Permalink to &quot;四、堆：用数组实现的完全二叉树&quot;">​</a></h3><p><strong>堆的两条性质</strong>：</p><ol><li><strong>结构性</strong>：是完全二叉树（除最后一层外都满，最后一层靠左）。</li><li><strong>有序性</strong>：大顶堆中，每个父节点 ≥ 两个孩子（小顶堆反之）。</li></ol><p><strong>为什么用数组存</strong>（关键）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        9</span></span>
<span class="line"><span>       / \\</span></span>
<span class="line"><span>      7   8</span></span>
<span class="line"><span>     / \\  /</span></span>
<span class="line"><span>    3  5 6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数组：[9, 7, 8, 3, 5, 6]</span></span>
<span class="line"><span>下标： 0  1  2  3  4  5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关系（0 起）：</span></span>
<span class="line"><span>  父 = (i - 1) / 2</span></span>
<span class="line"><span>  左孩子 = 2i + 1</span></span>
<span class="line"><span>  右孩子 = 2i + 2</span></span></code></pre></div><p><strong>完全二叉树用数组存，不浪费任何空间</strong>（普通二叉树用数组会浪费大量空位）。这是堆高效的根本原因——<strong>没有指针，缓存友好</strong>。</p><p><strong>三个核心操作</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 插入（上浮 sift-up）</span></span>
<span class="line"><span>   放到数组末尾 &gt; 和父节点比较 &gt; 比父大就交换 &gt; 一直往上</span></span>
<span class="line"><span>   O(log n)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 删除堆顶（下沉 sift-down）</span></span>
<span class="line"><span>   把最后一个元素放到堆顶 &gt; 和较大的孩子比较 &gt; 比孩子小就交换 &gt; 一直往下</span></span>
<span class="line"><span>   O(log n)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 建堆（heapify）</span></span>
<span class="line"><span>   从最后一个非叶子节点开始，依次下沉</span></span>
<span class="line"><span>   复杂度 O(n)，不是 O(n log n)！</span></span></code></pre></div><p><strong>&quot;建堆是 O(n)&quot;是高频考点</strong>：虽然每个节点下沉最多 O(log n)，但大部分节点在底层、下沉距离很短。数学求和后是 O(n)。直观理解：<strong>越往下节点越多，但下沉越少</strong>。</p><h3 id="五、跳表-redis-的选择" tabindex="-1">五、跳表（Redis 的选择） <a class="header-anchor" href="#五、跳表-redis-的选择" aria-label="Permalink to &quot;五、跳表（Redis 的选择）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有序链表查找 O(n)：</span></span>
<span class="line"><span>  1 &gt; 3 &gt; 5 &gt; 7 &gt; 9 &gt; 11 &gt; 13 &gt; 15</span></span>
<span class="line"><span></span></span>
<span class="line"><span>加多级索引后：</span></span>
<span class="line"><span>  L2:  1 --------&gt; 7 --------&gt; 13</span></span>
<span class="line"><span>  L1:  1 --&gt; 3 --&gt; 7 --&gt; 9 --&gt; 13 --&gt; 15</span></span>
<span class="line"><span>  L0:  1 &gt; 3 &gt; 5 &gt; 7 &gt; 9 &gt; 11 &gt; 13 &gt; 15</span></span>
<span class="line"><span></span></span>
<span class="line"><span>查找 11：L2 到 7 &gt; L1 到 9 &gt; L0 到 11    （3 步而不是 6 步）</span></span></code></pre></div><p><strong>跳表 vs 红黑树</strong>：</p><ul><li>跳表实现简单得多（不用旋转，只有指针操作）。</li><li>范围查询天然支持（底层是链表，顺序扫）。</li><li>并发友好（改局部指针即可，锁粒度小）。</li><li>代价：空间换时间（每层索引额外指针），最坏情况 O(n)（但概率极低）。</li></ul><p><strong>Redis 的 ZSet 用跳表</strong>，就是因为&quot;范围查询 + 实现简单 + 并发友好&quot;这三点。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果-bst-不平衡" tabindex="-1">反事实 1：如果 BST 不平衡 <a class="header-anchor" href="#反事实-1-如果-bst-不平衡" aria-label="Permalink to &quot;反事实 1：如果 BST 不平衡&quot;">​</a></h3><p>退化成链表，查找 O(n)。<strong>这就是为什么需要平衡树</strong>——不是为了&quot;更快&quot;，是为了<strong>保证最坏情况也是 O(log n)</strong>。</p><h3 id="反事实-2-如果堆要求全局有序" tabindex="-1">反事实 2：如果堆要求全局有序 <a class="header-anchor" href="#反事实-2-如果堆要求全局有序" aria-label="Permalink to &quot;反事实 2：如果堆要求全局有序&quot;">​</a></h3><p>那就得用排序数组：插入 O(n)（要挪动），取最值 O(1)。 堆只要求&quot;局部有序&quot;：插入 O(log n)，取最值 O(1)。<strong>用&quot;放弃全局有序&quot;换&quot;插入快&quot;</strong>。</p><p>这就是堆的价值：<strong>只在你需要的那个维度上保持有序</strong>。</p><h3 id="反事实-3-如果树每个节点只存一个值-接数据库" tabindex="-1">反事实 3：如果树每个节点只存一个值（接数据库） <a class="header-anchor" href="#反事实-3-如果树每个节点只存一个值-接数据库" aria-label="Permalink to &quot;反事实 3：如果树每个节点只存一个值（接数据库）&quot;">​</a></h3><p>1000 万条数据，二叉树高 ≈ log₂(1000万) ≈ 24 层。 每层一次磁盘 IO &gt; <strong>24 次 IO</strong>，每次 10ms &gt; <strong>240ms</strong>。</p><p>如果每个节点能存 500 个值（多叉树），树高降到 log₅₀₀(1000万) ≈ 3 层 &gt; <strong>3 次 IO，30ms</strong>。</p><p><strong>这就是 B 树 / B+ 树存在的理由</strong>（详见 <a href="/study-hub/bagu/db/01">索引与 B+ 树</a>）。二叉树在内存里很好，但在磁盘上不行——因为<strong>磁盘 IO 的次数 = 树高</strong>。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：二叉树的遍历方式？</strong></p><blockquote><p>四种：前序（根左右）、中序（左根右）、后序（左右根）、层序（BFS 用队列）。 <strong>必补一句</strong>：BST 的中序遍历是升序，所以&quot;验证 BST&quot;可以中序遍历看是否递增。</p></blockquote><p><strong>Q：为什么需要平衡树？</strong></p><blockquote><p>因为普通 BST 的形态由插入顺序决定，有序插入会退化成链表，查找从 O(log n) 变成 O(n)。平衡树通过旋转保证树高始终是 O(log n)，<strong>保证最坏情况</strong>。</p></blockquote><p><strong>Q：红黑树和 AVL 的区别？</strong></p><blockquote><p>AVL 严格平衡（高度差 ≤1），查找快但插入删除旋转多；红黑树宽松平衡（最长 ≤ 2×最短），插入删除更快。工程上多用红黑树，因为写操作更频繁。</p></blockquote><p><strong>Q：堆的插入和删除怎么做？复杂度？</strong></p><blockquote><p>插入：放末尾，上浮，O(log n)。 删除堆顶：末尾元素换到堆顶，下沉，O(log n)。 <strong>加分</strong>：建堆是 O(n)，不是 O(n log n)。</p></blockquote><p><strong>Q：为什么堆用数组存？</strong></p><blockquote><p>因为堆是完全二叉树，可以用下标直接算出父子关系（<code>2i+1</code>、<code>2i+2</code>），不需要指针。省空间、缓存友好、实现简单。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>二叉树有什么用？</span></span>
<span class="line"><span>  &gt; BST 查找多快？（O(树高)）</span></span>
<span class="line"><span>    &gt; 什么情况下变慢？（有序插入 &gt; 退化成链表 &gt; O(n)）</span></span>
<span class="line"><span>      &gt; 怎么解决？（平衡树：AVL / 红黑树）</span></span>
<span class="line"><span>        &gt; 为什么工程上用红黑树？（旋转少，写性能好）</span></span>
<span class="line"><span>          &gt; 那数据库为什么不用红黑树？（树太高，磁盘 IO 次数多）</span></span>
<span class="line"><span>            &gt; 用什么？（B+ 树，多叉，树高 3~4 层）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/dsa/01">复杂度与数组、链表</a>：堆用数组存，完全二叉树的下标关系是数组特性的应用</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/dsa/02">栈、队列与哈希表</a>：优先队列的实现是堆；HashMap 冲突严重转红黑树</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/dsa/04">图与并查集</a>：Dijkstra 用优先队列（堆）优化；并查集用&quot;按秩合并&quot;控制树高</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/01">索引与 B+ 树</a>：<strong>这是最重要的一条连接</strong>——B+ 树是&quot;多叉平衡树 + 叶子链表&quot;，解决了二叉树在磁盘上树高过大的问题</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/dsa/05">排序与二分</a>：堆排序、Top K 问题</li><li><strong>&gt; 影响</strong> 工程实践：Java <code>TreeMap</code>（红黑树）、<code>PriorityQueue</code>（堆）、Redis <code>ZSet</code>（跳表）、Linux 内核的 CFS 调度器（红黑树）</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么建堆是 O(n)，而&quot;插入 n 次&quot;是 O(n log n)？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>下沉的节点数和下沉深度成反比</strong>。</p><p>完全二叉树中：</p><ul><li>约 <strong>一半</strong>的节点是叶子，下沉 0 层。</li><li>约 <strong>1/4</strong> 的节点在倒数第二层，最多下沉 1 层。</li><li>约 <strong>1/8</strong> 的节点最多下沉 2 层。</li><li>...</li></ul><p>总代价 ≈ <code>n/2×0 + n/4×1 + n/8×2 + ...</code>，这个级数收敛到 <strong>O(n)</strong>。</p><p>而&quot;插入 n 次&quot;是每个元素都从<strong>底部</strong>开始上浮，平均上浮 log n 层，所以是 O(n log n)。</p><p><strong>直觉</strong>：建堆是从下往上，大部分节点在底部、几乎不用动；插入是从上往下，每个都要走完全程。</p></details><p><strong>Q2：为什么数据库不用红黑树做索引？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>树太高，磁盘 IO 次数太多</strong>。</p><p>红黑树是二叉树，1000 万条数据树高约 24 层。数据库索引存在磁盘上，<strong>每访问一个节点就是一次磁盘 IO</strong>（即使有缓存，未命中时也要 10ms 级）。24 次 IO = 240ms，无法接受。</p><p>B+ 树是多叉树，一个节点就是一个磁盘页（16KB），能存几百个键。树高降到 3~4 层，只需 3~4 次 IO。</p><p><strong>根本区别</strong>：内存里访问节点几乎免费，所以二叉树够用；磁盘上访问节点极贵，必须<strong>减少访问次数</strong>，也就是<strong>降低树高</strong>，也就是<strong>增加分叉数</strong>。</p><p>这也是&quot;数据结构的选择依赖于存储介质&quot;的经典例子。</p></details><p><strong>Q3：堆能不能做范围查询？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>不能</strong>（高效地）。</p><p>堆只保证&quot;父节点 ≥ 子节点&quot;，兄弟之间、父子之外的节点之间<strong>没有任何顺序关系</strong>。</p><p>所以查&quot;所有大于 50 的元素&quot;：</p><ul><li>堆顶是最大值，但第二大在哪？不知道，可能在第二层任意位置。</li><li>只能全遍历 O(n)。</li></ul><p>堆适合的场景只有：<strong>反复取最值</strong>（优先队列、Top K、任务调度）。一旦需要&quot;有序遍历&quot;或&quot;范围查询&quot;，就得用平衡树或排序数组。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;族谱&quot;类比会让人以为树一定是二叉的</strong>。实际有多叉树（B 树、字典树 Trie）。</li><li><strong>&quot;平衡树查找更快&quot;不严谨</strong>。平衡树不是&quot;比 BST 快&quot;，是&quot;<strong>保证最坏情况不退化</strong>&quot;。数据随机时，普通 BST 平均也是 O(log n)。</li><li><strong>堆不等于有序</strong>。堆只能保证堆顶是极值，中间元素无序。<strong>堆排序</strong>之所以能排序，是因为反复&quot;取堆顶 + 下沉&quot;。</li><li><strong>红黑树不是&quot;完全平衡&quot;</strong>。它允许最长路径是最短路径的 2 倍，所以查找最坏是 2log n，不是严格 log n。</li><li><strong>&quot;完全二叉树&quot;和&quot;满二叉树&quot;不是一回事</strong>。满二叉树是每层都满；完全二叉树只要求&quot;最后一层靠左连续&quot;。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能默写二叉树四种遍历的序列，并说出各自的典型用途</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能解释&quot;BST 为什么会退化成链表&quot;，并画出退化后的样子</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出 AVL 和红黑树的区别，以及工程上为什么多用红黑树</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能写出堆的数组下标关系（父、左孩子、右孩子），并解释&quot;为什么堆用数组存&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说清堆的插入（上浮）和删除（下沉）步骤，复杂度各是多少</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能解释&quot;建堆为什么是 O(n) 而不是 O(n log n)&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能说出&quot;数据库为什么不用红黑树&quot;（要提到树高与磁盘 IO 次数的关系）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 能说出堆不能做范围查询的原因</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="8"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,73)])])}const h=a(l,[["render",o]]);export{u as __pageData,h as default};
